}

struct Info { bool bst; long long lo, hi, sum; };

Info post(TreeNode* node, long long& best) {
    if (node == nullptr) return {true, LLONG_MAX, LLONG_MIN, 0};
    Info l = post(node->left, best), r = post(node->right, best);
    if (l.bst && r.bst && l.hi < node->val && node->val < r.lo) {
        long long sum = l.sum + node->val + r.sum;
        best = max(best, sum);
        return {true, min(l.lo, (long long)node->val), max(r.hi, (long long)node->val), sum};
    }
    return {false, 0, 0, 0};                         // not a BST: no ancestor can be one either
}

int maxSumBST(TreeNode* root) {
    long long best = 0;
    post(root, best);
    return (int)best;
}
